-- THE SHINICHI KUDO PROTOCOL | SAFE v2 | MySQL 8.0.16+
-- Fictional, deterministic dataset. This script is safe to run twice:
-- after the first successful import, it prints ALREADY_SEEDED_NO_CHANGES.
-- The actual inserts occur atomically in a stored procedure after a strict
-- installation-marker and empty-table check. On error: ROLLBACK + RESIGNAL.
-- Note: a temporary helper PROCEDURE is replaced/removed; DATA TABLES are
-- NEVER dropped, truncated, cleared or overwritten by this script.
-- SQL times in this demo are UTC, 2026-12-04.
USE shinichi_forensic_demo_v2;

-- Replace our own temporary helper if a previous interrupted run left it.
DROP PROCEDURE IF EXISTS seed_shinichi_safe_v2;
DELIMITER $$
CREATE PROCEDURE seed_shinichi_safe_v2()
BEGIN
  DECLARE previous_seed_at DATETIME(3) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;
  IF NOT EXISTS (
    SELECT 1 FROM project_installation
    WHERE install_id = 1 AND project_code = 'shinichi-kudo-forensics-safe-v2'
      AND schema_version = 2
  ) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Unrecognized project installation: refusing data import';
  END IF;

  SELECT seeded_at INTO previous_seed_at
  FROM project_installation WHERE install_id = 1 FOR UPDATE;

  IF previous_seed_at IS NOT NULL THEN
    COMMIT;
    SELECT 'ALREADY_SEEDED_NO_CHANGES' AS import_status,
           'Existing evidence was not modified. Run verification.sql.' AS detail;
  ELSE
    -- Fail CLOSED on partially filled or foreign tables; never mix datasets.
    IF (SELECT COUNT(*) FROM suspects) > 0
      OR (SELECT COUNT(*) FROM access_logs) > 0
      OR (SELECT COUNT(*) FROM acoustic_events) > 0
      OR (SELECT COUNT(*) FROM door_state_logs) > 0
      OR (SELECT COUNT(*) FROM camera_observations) > 0
      OR (SELECT COUNT(*) FROM fingerprint_sensors) > 0
      OR (SELECT COUNT(*) FROM dna_scanner_logs) > 0
      OR (SELECT COUNT(*) FROM scanner_integrity_exports) > 0
      OR (SELECT COUNT(*) FROM scanner_audit_events) > 0
      OR (SELECT COUNT(*) FROM ballistics_evidence) > 0
      OR (SELECT COUNT(*) FROM investigative_leads) > 0
    THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Tables already contain data: refusing to overwrite or mix rows';
    END IF;

    -- Begin deterministic fictional scene data. No real biological profiles.
    INSERT INTO suspects (suspect_id, full_name, role_in_event, dna_profile_hash, status) VALUES
